questionvariables.text:
/* Design backwards: choose the two legs; everything else follows.        */
/* AB is the vertical leg (opposite theta at C); BC is horizontal (adjacent). */
AB : 2 + rand(5);              /* 2 .. 6 */
BC : AB + 1 + rand(4);         /* AB+1 .. AB+4 : strictly longer than AB, so   */
                               /* sin(theta) # cos(theta) (the swap diagnostic */
                               /* is safe) and the diagram is always wide.     */
AC : sqrt(AB^2 + BC^2);        /* hypotenuse, usually a surd */

/* Model answers */
ta1 : AB/AC;                   /* sin(theta) */
ta2 : BC/AC;                   /* cos(theta) */
ta3 : AB/BC;                   /* tan(theta) */

/* Anticipated wrong answer: reciprocal of the tangent ratio */
wrong_tan_recip : BC/AB;
